--[=[
    @class WuKongServer
    @server

    本类为悟空框架的服务端管理类.

    主要提供服务端用户门面的相关操作功能.

]=]

local rs = game:GetService("ReplicatedStorage")
require(rs.WuKong.c2l)
local WuKongFacade = require(rs.WuKong.WuKongFacade)
local api = require(script.WuKongServerCsApi)
local wukongConfig = require(game.ReplicatedStorage.WuKong.Configuration)
local WuKongServer = {}
local WukongDebugger = require(game.ReplicatedStorage.WuKong.WuKongDebugger)
require(script.PurchaseHandler)
--[=[
	判断是否含有用户门面
]=]
function WuKongServer.HasFacade(userId: number): boolean
	return api.HasFacade(userId)
end

--[=[
    获取用户门面,只有注册到同步中心后，才可以获取到门面
    @return WuKongServerUserFacade
]=]
function WuKongServer.GetFacade(userId: number)
	return api.GetFacade(userId)
end

--[=[
    等到用户门面,直到注册到同步中心或者用户离线
    @return WuKongServerUserFacade
]=]
function WuKongServer.WaitFacade(userId: number)
	local facade
	-- 如果没有获取到门面，等待获取，直到获取到门面或者用户离线
	repeat
		if api.HasFacade(userId) then
			facade = api.GetFacade(userId)
		else
			wait()
		end

	until facade or not game.Players:GetPlayerByUserId(userId)
	return facade
end

--[=[
	将用户注册到悟空服务器
	@param userData any? -- 用户序列化后的数据， 如果为空则创建新用户容器
	@return WuKongFacade.Type -- 用户门面
]=]
function WuKongServer.RegisterUser(userId: number, userData: any?): WuKongFacade.Type
	local container = nil
	if wukongConfig.HasConfig("重置用户数据开关") and wukongConfig.GetConfig("重置用户数据开关") then
		-- 创建新用户数据
		container = api.CreateWuKongContainer(userId)
	elseif userData then
		container = api.DeserializeWuKongContainer(userId, userData)
	else
		-- 创建新用户数据
		container = api.CreateWuKongContainer(userId)
	end

	-- 注册到悟空
	local facade = api.Register(container)
	return facade
end

--[=[
	将用户从悟空服务器注销
	@param userId
	@return {}? -- 返回空,说明用户未在悟空服务器注册,否则返回用户序列化后的数据,供入库
]=]
function WuKongServer.UnregisterUser(userId: number): {}?
	if not api.HasFacade(userId) then
		return
	end

	local facade = api.GetFacade(userId)

	local container = facade:GetContainer()

	facade:Dispose()

	api.UnRegister(userId)

	return api.SerializeWuKongContainer(container)
end

--[=[
	用户注册到悟空服务器事件
	注意： 事件的第二个参数为一个函数，调用此函数可以对应的用户门面，由于事件中不能传递复杂表，只能这么麻烦了。
]=]
function WuKongServer.ConnectUserRegisterEvent(
	func: (userId: number, facadeProvider: () -> WuKongFacade.Type) -> ()
): RBXScriptConnection
	-- 及时在调用此方法前存在 Facades 了，也能保证注册事件一定会被调用
	local facade = api.GetAllFacades()
	for userId, _ in pairs(facade) do
		pcall(func, userId, function()
			return facade
		end)
	end
	return script.UserRegisterEvent.Event:Connect(func)
end

--[=[
	用户从悟空服务器取消注册事件
]=]
function WuKongServer.ConnectUserUnRegisterEvent(func: (userId: number) -> ()): RBXScriptConnection
	return script.UserUnRegisterEvent.Event:Connect(func)
end

--[=[
	允许调试器更改用户数据
]=]
function WuKongServer.EnableDebuggerChangeUserData(
	loadDataHandler: (userId: number) -> {},
	saveDataHandler: (userId: number, data: any) -> {}
)
	WukongDebugger.EnableDebuggerChangeUserData(loadDataHandler, saveDataHandler)
end

return WuKongServer
